def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z]+\d*|<>|<=|>=|[-+*/(),:=<>]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "~": 3,
        ":": 4,
    }

    def integer(text):
        text = text.strip()
        if len(text) <= 4000:
            return int(text)

        sign = 1
        if text[0] in "+-":
            if text[0] == "-":
                sign = -1
            text = text[1:]

        value = 0
        for i in range(0, len(text), 9):
            chunk = text[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return sign * value

    def parse(formula):
        tokens = token_pattern.findall(formula)
        nodes = []
        operators = []

        def reduce_operator():
            op = operators.pop()
            if op == "~":
                nodes.append((op, nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        expecting_operand = True
        i = 0

        while i < len(tokens):
            token = tokens[i]

            if token[0].isdigit():
                nodes.append(integer(token))
                expecting_operand = False

            elif token in functions:
                # A marker stores the function and its argument count.
                operators.append([token, 1])
                i += 1  # Consume the following opening parenthesis.
                expecting_operand = True

            elif token[0].isalpha():
                nodes.append(token)
                expecting_operand = False

            elif token == "(":
                operators.append([None, 0])
                expecting_operand = True

            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                operators[-1][1] += 1
                expecting_operand = True

            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                function, count = operators.pop()

                if function is not None:
                    args = tuple(nodes[-count:])
                    del nodes[-count:]
                    nodes.append((function, args))

                expecting_operand = False

            else:
                op = "~" if token == "-" and expecting_operand else token

                while operators and isinstance(operators[-1], str):
                    top = operators[-1]
                    if (
                        precedence[top] > precedence[op]
                        or (
                            precedence[top] == precedence[op]
                            and op != "~"
                        )
                    ):
                        reduce_operator()
                    else:
                        break

                operators.append(op)
                expecting_operand = True

            i += 1

        while operators:
            reduce_operator()

        return nodes[0]

    def argument_nodes(args):
        for arg in args:
            if isinstance(arg, tuple) and arg[0] == ":":
                first, last = arg[1], arg[2]
                left, right = sorted((ord(first[0]), ord(last[0])))
                top, bottom = sorted((int(first[1:]), int(last[1:])))

                for row in range(top, bottom + 1):
                    for column in range(left, right + 1):
                        name = chr(column) + str(row)
                        if name in cells:
                            yield name
            else:
                yield arg

    # A cell is absent from state, currently active (1), or finished (2).
    state = {}
    values = {}
    result = 0

    for root in cells:
        if state.get(root) == 2:
            continue

        work = [("cell", root)]

        while work:
            task = work.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]

                if name not in cells:
                    result = 0
                elif state.get(name) == 2:
                    result = values[name]
                elif state.get(name) == 1:
                    result = "#CYCLE!"
                else:
                    state[name] = 1
                    content = cells[name]
                    node = (
                        parse(content[1:])
                        if content.startswith("=")
                        else integer(content)
                    )
                    work.append(("finish_cell", name))
                    work.append(("expression", node))

            elif kind == "finish_cell":
                name = task[1]
                values[name] = result
                state[name] = 2

            elif kind == "expression":
                node = task[1]

                if isinstance(node, int):
                    result = node
                elif isinstance(node, str):
                    work.append(("cell", node))
                else:
                    op = node[0]

                    if op == "~":
                        work.append(("negate",))
                        work.append(("expression", node[1]))

                    elif op == "IF":
                        condition, then_branch, else_branch = node[1]
                        work.append(("choose", then_branch, else_branch))
                        work.append(("expression", condition))

                    elif op in ("SUM", "MIN", "MAX"):
                        work.append((
                            "aggregate_next", op, argument_nodes(node[1]), None
                        ))

                    else:
                        work.append(("binary_left", op, node[2]))
                        work.append(("expression", node[1]))

            elif kind == "negate":
                if not isinstance(result, str):
                    result = -result

            elif kind == "choose":
                if not isinstance(result, str):
                    branch = task[1] if result else task[2]
                    work.append(("expression", branch))

            elif kind == "binary_left":
                if not isinstance(result, str):
                    work.append(("binary_right", task[1], result))
                    work.append(("expression", task[2]))

            elif kind == "binary_right":
                if isinstance(result, str):
                    continue

                op, left = task[1], task[2]
                right = result

                if op == "+":
                    result = left + right
                elif op == "-":
                    result = left - right
                elif op == "*":
                    result = left * right
                elif op == "/":
                    if right == 0:
                        result = "#DIV/0!"
                    else:
                        quotient = abs(left) // abs(right)
                        result = (
                            -quotient
                            if (left < 0) != (right < 0)
                            else quotient
                        )
                elif op == "=":
                    result = left == right
                elif op == "<>":
                    result = left != right
                elif op == "<":
                    result = left < right
                elif op == "<=":
                    result = left <= right
                elif op == ">":
                    result = left > right
                elif op == ">=":
                    result = left >= right

            elif kind == "aggregate_next":
                op, iterator, accumulated = task[1:]
                try:
                    node = next(iterator)
                except StopIteration:
                    result = 0 if accumulated is None else accumulated
                else:
                    work.append((
                        "aggregate_take", op, iterator, accumulated
                    ))
                    work.append(("expression", node))

            elif kind == "aggregate_take":
                if isinstance(result, str):
                    continue

                op, iterator, accumulated = task[1:]

                if accumulated is None:
                    accumulated = result
                elif op == "SUM":
                    accumulated += result
                elif op == "MIN":
                    accumulated = min(accumulated, result)
                else:
                    accumulated = max(accumulated, result)

                work.append((
                    "aggregate_next", op, iterator, accumulated
                ))

    return {name: values[name] for name in cells}
